def T(omega, lam, R, M=1.0, v_s2=0.0):
    a = A(omega, lam, R, M, v_s2)
    b = B(omega, lam, R, M, v_s2)
    X = np.linalg.lstsq(a, b, rcond=None)[0]
    return X[-2:, :]

def residual(omega, lam, R, M=1.0, v_s2=0.0):
    a = A(omega, lam, R, M, v_s2); b = B(omega, lam, R, M, v_s2)
    X = np.linalg.lstsq(a, b, rcond=None)[0]
    return np.abs(a @ X - b).max() / np.abs(b).max()
